  ('rootcause', 'Wrong PM Calls created (Sale invoice cancelled)', jsonb_build_object('product', 'MONNAL T75'), date '2023-11-06', 'rithi.adm@gmail.com'),
  ('rootcause', 'WRONG PM CALLS CREATED (SOFTWARE ISSUE)', jsonb_build_object('product', 'MONNAL T75'), date '2023-11-06', 'rithi.adm@gmail.com'),
  ('rootcause', 'Wrong sl.no. entered', jsonb_build_object('product', 'MONNAL T75'), date '2023-11-06', 'rithi.adm@gmail.com'),
  ('rootcause', 'Wrong supply', jsonb_build_object('product', 'MONNAL T75'), date '2023-11-06', 'rithi.adm@gmail.com'),
  ('rootcause', 'Wrong supply (Dealer)', jsonb_build_object('product', 'MONNAL T75'), date '2023-11-06', 'rithi.adm@gmail.com'),
  ('rootcause', 'Wrongly entered dealer name.', jsonb_build_object('product', 'MONNAL T75'), date '2023-11-06', 'rithi.adm@gmail.com'),
  ('rootcause', 'Customer Denied', jsonb_build_object('product', 'MONNAL T75'), date '2023-11-06', 'rithi.adm@gmail.com'),
